// Package plainjsonpb is the runtime imported by code generated by
// protoc-gen-go-plainjson.
//
// Generated marshalers are one-way: they flatten a protobuf message into a
// JSON object and cannot read it back. See the repository README for the
// option reference that drives generation.
package plainjsonpb

import (
	"fmt"
	"strings"

	"github.com/go-faster/jx"
)

// Marshaler is implemented by every message the plugin generates for.
type Marshaler interface {
	// EncodePlainJSON writes the flattened form into e.
	EncodePlainJSON(e *jx.Encoder) error
	// MarshalPlainJSON returns the flattened form.
	MarshalPlainJSON() ([]byte, error)
}

// KeyCollisionError reports two live sources writing the same JSON key under
// COLLISION_POLICY_ERROR_RUNTIME.
type KeyCollisionError struct {
	// Key is the JSON key written twice.
	Key string
	// First and Second are the source paths, in traversal order. A dynamic
	// source is spelled with its origin, for example `labels[name]`.
	First, Second string
}

func (e *KeyCollisionError) Error() string {
	return fmt.Sprintf("plainjson: key %q written by both %s and %s", e.Key, e.First, e.Second)
}

// MergeConflictError reports a merge rule with MERGE_CONFLICT_ERROR whose
// sources were non-empty at the same time.
type MergeConflictError struct {
	// Key is the merged JSON key.
	Key string
	// Paths are the source paths that held a value, in declaration order.
	Paths []string
}

func (e *MergeConflictError) Error() string {
	return fmt.Sprintf("plainjson: merge %q has %d non-empty sources: %s",
		e.Key, len(e.Paths), strings.Join(e.Paths, ", "))
}
